/bin/zsh -lc "python3 - <<'PY'
import os,re
root='.'
files=[]
for dp,ds,fs in os.walk(root):
    if '/src/main/java' not in dp: continue
    for f in fs:
        if f.endswith('.java'): files.append(os.path.join(dp,f))
classes={}; info={}
for p in files:
    s=open(p).read()
    s2=re.sub(r'/\\*.*?\\*/',' ',s,flags=re.S); s2=re.sub(r'//.*',' ',s2)
    pkg=re.search(r'\\bpackage\\s+([\\w.]+)',s2); pkg=pkg.group(1) if pkg else ''
    imps=dict((x.split('.')[-1],x) for x in re.findall(r'\\bimport\\s+(?:static\\s+)?([\\w.]+)\\s*;',s2))
    # first top-level-ish declaration after removing annotations; works primary class
    decl=list(re.finditer(r'\\b(public\\s+|protected\\s+|private\\s+|abstract\\s+|final\\s+|static\\s+)*\\b(class|interface|enum|@interface)\\s+(\\w+)',s2))
    if not decl: continue
    # map every declared name to file, but nested can collide; primary all relevant
    primary=decl[0].group(3)
    fq=(pkg+'.'+primary if pkg else primary)
    classes[fq]=p
    info[p]=(pkg,imps,primary,s2)
# symbol -> fq candidates
byshort={}
for fq,p in classes.items(): byshort.setdefault(fq.split('.')[-1],[]).append(fq)
# graph broad: imported project symbols and same-package project symbols whose token appears in code
G={p:set() for p in files}
for p,(pkg,imps,primary,s) in info.items():
    body=re.sub(r'\\bimport\\b.*?;',' ',s,flags=re.S)
    toks=set(re.findall(r'\\b[A-Z]\\w*\\b',body))
    for short,fqs in byshort.items():
        if short not in toks: continue
        # resolve import/same package; if multiple, include matching imported or same-package
        choices=[]
        if short in imps and imps[short] in classes: choices=[imps[short]]
        elif len([x for x in fqs if x.startswith(pkg+'.')])==1: choices=[x for x in fqs if x.startswith(pkg+'.')]
        elif len(fqs)==1: choices=fqs
        for fq in choices:
            if classes[fq]"'!=p: G[p].add(classes[fq])
# target fq
names=['"'CustomerService','ProductService','PricingService','UserFacade','StoreFacade','EmailService','CountryService','OrderFacade']
for name in names:
    print('\\nTARGET',name)
    for fq,p in classes.items():
        if fq.endswith('.'+name):
            print(' target',fq,p)
            direct=[os.path.basename(a) for a,b in G.items() if p in b]
            print(' direct:',', '.join(sorted(direct)))
            affected={p}; changed=True
            while changed:
                changed=False
                for a,b in G.items():
                    if a not in affected and b & affected: affected.add(a); changed=True
            ctr=[]
            for a in affected:
                if a in info and re.search(r'@(RestController|Controller)\\b',info[a][3]): ctr.append(info[a][2])
            print(' controllers:',', '.join(sorted(ctr)))
            if name=='OrderFacade': print(' all affected:',', '.join(sorted(info[a][2] for a in affected if a in info)))
PY"
